solution:
.weather {
  width: 340px;
  margin: 24px;
  padding: 20px;
  font-family: system-ui, sans-serif;
}

.weather p {
  margin: 0;
}

.forecast {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ---- Solution ---- */
.weather {
  border-radius: 20px;
  background-image: linear-gradient(160deg, #38bdf8, #6366f1);
  box-shadow: 0 12px 30px rgb(99 102 241 / 0.35);
  color: #ffffff;
}

.now {
  display: flex;
  align-items: center;
  gap: 16px;
}

.icon {
  position: relative;
  width: 80px;
  height: 64px;
}

.sun {
  position: absolute;
  top: 0;
  right: 4px;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background-color: #fde047;
  box-shadow: 0 0 20px rgb(253 224 71 / 0.8);
}

.cloud {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 64px;
  height: 30px;
  border-radius: 999px;
  background-color: #ffffff;
}

.cloud::before {
  content: "";
  position: absolute;
  bottom: 12px;
  left: 14px;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-color: #ffffff;
}

.temp {
  font-size: 56px;
  font-weight: 200;
  line-height: 1;
}

.desc {
  font-size: 13px;
  opacity: 0.85;
}

.forecast {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: 20px;
}

.day {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 10px 0;
  border-radius: 12px;
  background-color: rgb(255 255 255 / 0.18);
  font-size: 13px;
}

.day-temp {
  font-weight: 600;
}
